int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T, N;
    cin >> T >> N;

    vector<int> x(N);
    for (int i = 0; i < N; ++i) {
        cin >> x[i];
    }

    sort(x.begin(), x.end());

    double ans = 1e18;

    for (int i = 0; i < N; ++i) {
        double left = (i == 0) ? 0.0 : (x[i - 1] + x[i]) / 2.0;
        double right = (i == N - 1) ? (double)T : (x[i] + x[i + 1]) / 2.0;
        ans = min(ans, right - left);
    }

    cout << fixed << setprecision(2) << ans << '\n';

    return 0;
}
